  ('990ff225-fb3b-54e7-a1ac-93d2e4fdc0dd'::uuid, 9, 'Keyboard Shortcuts', 'medium', 'To type a single capital letter or the "@" symbol above the number 2 without turning on Caps Lock, which key do you hold?', 'Alt', 'Shift', 'Tab', 'Ctrl', 'b', 'To type a single capital letter or the "@" symbol above the number 2 without turning on Caps Lock, which key do you hold?', 'AltGr', 'Shift', 'Enter', 'Space'),
  ('77de1a67-651e-5324-8a45-2b76d2d7cf36'::uuid, 9, 'Keyboard Shortcuts', 'medium', 'Which shortcut opens a brand-new blank document or window in most apps?', 'Ctrl + N', 'Ctrl + B', 'Ctrl + M', 'Ctrl + D', 'a', 'Which shortcut opens a brand-new blank document or window in most apps?', 'Ctrl + N', 'Ctrl + B', 'Ctrl + M', 'Ctrl + D'),
