-- REVISED OLD QUESTION BANK: 756 questions (108 per class, classes 6-12).
-- Source: repository commit 9750f2514720764ae7a757090fff2b8a242c089a.
-- SECURITY WARNING: The original questions and answer keys are public in Git
-- history. Changing the distractors and deleting this file will NOT make them
-- secret. Do not use the exposed bank for secure or high-stakes exams.
--
-- Run the complete supabase/schema.sql first (back up before its first run).
-- This script intentionally activates these legacy questions as bank_generation=2
-- so the app can use them. It keeps answer positions and class assignments.
-- It inserts missing rows, and updates old rows only when every original field
-- still matches exactly. Teacher-edited, inactive, and other questions are never
-- overwritten or deleted. Re-running is safe. Existing exam snapshots are unchanged.
-- 650 question rows were revised; 106 were reviewed and left unchanged.
-- Options are edited for comparable length; review content with a teacher. A
-- length heuristic does not prove fairness or eliminate every possible clue.
-- This temporary seed is published and includes its answer key. Use a newly
-- created private bank for real exams; this legacy bank is compromised.

BEGIN;
SET LOCAL standard_conforming_strings = on;
DO $$
BEGIN
  IF to_regclass('public.questions') IS NULL OR to_regclass('public.mtc_migrations') IS NULL THEN
    RAISE EXCEPTION 'Apply the complete supabase/schema.sql before running this seed';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.mtc_migrations WHERE name = 'private-bank-and-credentials-v1') THEN
    RAISE EXCEPTION 'Apply the complete supabase/schema.sql before running this seed';
  END IF;
END $$;
DROP TABLE IF EXISTS pg_temp.mtc_revised_seed_report_20261030;
CREATE TEMP TABLE mtc_revised_seed_20261030 (
  seed_id uuid PRIMARY KEY, class integer NOT NULL, subject_tag text NOT NULL, difficulty text NOT NULL,
  old_question text NOT NULL, old_a text NOT NULL, old_b text NOT NULL, old_c text NOT NULL, old_d text NOT NULL,
  correct_option text NOT NULL, new_question text NOT NULL, new_a text NOT NULL, new_b text NOT NULL, new_c text NOT NULL, new_d text NOT NULL
) ON COMMIT DROP;

-- Class 6: all 108 questions.

-- Class 7: all 108 questions.

-- Class 8: all 108 questions.

-- Class 9: all 108 questions.

-- Class 10: all 108 questions.

-- Class 11: all 108 questions.

-- Class 12: all 108 questions.

-- If a previous seed was run, revise only rows that still exactly match the
-- original. This also handles identical old questions imported with another ID.
UPDATE public.questions AS q
SET question_text = s.new_question, option_a = s.new_a, option_b = s.new_b,
    option_c = s.new_c, option_d = s.new_d
FROM pg_temp.mtc_revised_seed_20261030 AS s
WHERE q.class = s.class AND q.subject_tag = s.subject_tag AND q.difficulty = s.difficulty
  AND q.is_active = true AND q.bank_generation >= 2
  AND q.question_text = s.old_question AND q.correct_option = s.correct_option
  AND q.option_a = s.old_a AND q.option_b = s.old_b AND q.option_c = s.old_c AND q.option_d = s.old_d
  AND (s.old_question, s.old_a, s.old_b, s.old_c, s.old_d)
      IS DISTINCT FROM (s.new_question, s.new_a, s.new_b, s.new_c, s.new_d);

-- Insert missing legacy rows. Matching active questions and existing deterministic
-- IDs are left untouched to avoid duplicates and preserve teacher edits.
SELECT s.seed_id, s.class, s.subject_tag, s.difficulty, s.new_question,
       s.new_a, s.new_b, s.new_c, s.new_d, s.correct_option, true, 2
FROM pg_temp.mtc_revised_seed_20261030 AS s
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions q
  WHERE q.class = s.class AND q.is_active = true AND q.bank_generation >= 2
    AND q.question_text IN (s.old_question, s.new_question)
)
ON CONFLICT (id) DO NOTHING;

-- The report contains counts only; the question/answer staging table is dropped
-- at commit. Edited or inactive matches remain untouched for teacher review.
CREATE TEMP TABLE mtc_revised_seed_report_20261030 ON COMMIT PRESERVE ROWS AS
SELECT s.class, count(*)::integer AS expected,
  count(*) FILTER (WHERE EXISTS (
    SELECT 1 FROM public.questions q
    WHERE q.class = s.class AND q.is_active = true AND q.bank_generation >= 2
      AND q.subject_tag = s.subject_tag AND q.difficulty = s.difficulty
      AND q.question_text = s.new_question AND q.correct_option = s.correct_option
      AND q.option_a = s.new_a AND q.option_b = s.new_b AND q.option_c = s.new_c AND q.option_d = s.new_d
  ))::integer AS revised_ready,
  count(*) FILTER (WHERE NOT EXISTS (
    SELECT 1 FROM public.questions q
    WHERE q.class = s.class AND q.is_active = true AND q.bank_generation >= 2
      AND q.subject_tag = s.subject_tag AND q.difficulty = s.difficulty
      AND q.question_text = s.new_question AND q.correct_option = s.correct_option
      AND q.option_a = s.new_a AND q.option_b = s.new_b AND q.option_c = s.new_c AND q.option_d = s.new_d
  ))::integer AS needs_review,
  sum((SELECT count(*) FROM public.questions q
    WHERE q.class = s.class AND q.is_active = true AND q.bank_generation >= 2
      AND (q.id = s.seed_id OR q.question_text IN (s.old_question, s.new_question))
      AND (q.subject_tag, q.difficulty, q.question_text, q.correct_option, q.option_a, q.option_b, q.option_c, q.option_d)
          IS DISTINCT FROM (s.subject_tag, s.difficulty, s.new_question, s.correct_option, s.new_a, s.new_b, s.new_c, s.new_d)
  ))::integer AS other_active_matches
FROM pg_temp.mtc_revised_seed_20261030 AS s GROUP BY s.class;
COMMIT;

-- Ideally each class shows expected=108, revised_ready=108, needs_review=0,
-- other_active_matches=0. A nonzero review count means an edited/inactive row
-- was not overwritten or a conflicting active copy needs a teacher's attention.
SELECT class, expected, revised_ready, needs_review, other_active_matches
FROM pg_temp.mtc_revised_seed_report_20261030 ORDER BY class;
